#!/usr/bin/env Rscript
#
# Detect Events and Save with Transcript IDs
#
# Detects all splicing events between dominant/comparator isoform pairs and
# writes them to a TSV file for use by reconstruct_dominant_isoforms.R.
#
# The GTF may contain many isoforms per gene. The pairs file selects which
# two to compare per row; only those two transcripts are extracted from the GTF.
#
# Inputs:
#   - GTF file (may contain any number of isoforms per gene)
#   - Pairs file: gene_id, isoform_A (dominant), isoform_B (comparator), chr, strand
#     Generated by generate_pairs_from_dominant.R
#
# Outputs:
#   - Events TSV file with all required columns for reconstruction

library(tidyverse)

source("event_detection_functions.R")

# ==============================================================================
# Parse GTF
# ==============================================================================

#' Parse GTF file to extract exon information
#'
#' @param gtf_file Path to GTF file
#' @return Tibble with exon information (chr, exon_start, exon_end, strand,
#'         gene_id, transcript_id, exon_number)
parse_gtf <- function(gtf_file) {
  cat("Reading GTF file:", gtf_file, "\n")

  lines <- readLines(gtf_file)
  lines <- lines[!startsWith(lines, '#') & lines != '']

  results <- list()
  for (line in lines) {
    parts <- strsplit(line, '\t')[[1]]

    if (parts[3] != "exon") next

    attrs_str <- parts[9]
    gene_id <- sub('.*gene_id "([^"]+)".*', '\\1', attrs_str)
    transcript_id <- sub('.*transcript_id "([^"]+)".*', '\\1', attrs_str)

    exon_number_str <- sub('.*exon_number "([^"]+)".*', '\\1', attrs_str)
    exon_number <- if (grepl('exon_number', attrs_str)) as.integer(exon_number_str) else NA_integer_

    results[[length(results) + 1]] <- tibble(
      chr = parts[1],
      exon_start = as.integer(parts[4]),  # 1-based
      exon_end = as.integer(parts[5]),    # 1-based
      strand = parts[7],
      gene_id = gene_id,
      transcript_id = transcript_id,
      exon_number = exon_number
    )
  }

  gtf_data <- bind_rows(results)

  cat(sprintf("  Parsed %d exon records\n", nrow(gtf_data)))
  cat(sprintf("  %d genes, %d transcripts\n",
              n_distinct(gtf_data$gene_id),
              n_distinct(gtf_data$transcript_id)))

  return(gtf_data)
}

# ==============================================================================
# Main Pipeline
# ==============================================================================

main <- function(gtf_file, pairs_file, output_file) {
  cat("\n╔════════════════════════════════════════════════════════════════╗\n")
  cat("║   Event Detection and Export Pipeline                         ║\n")
  cat("╚════════════════════════════════════════════════════════════════╝\n\n")

  gtf_data <- parse_gtf(gtf_file)

  pairs <- read_tsv(pairs_file, show_col_types = FALSE)

  cat(sprintf("\nProcessing %d pairs...\n", nrow(pairs)))

  all_events <- list()

  for (i in seq_len(nrow(pairs))) {
    pair <- pairs[i, ]

    cat(sprintf("\n[%d/%d] %s\n", i, nrow(pairs), pair$gene_id))

    # isoform_A = dominant, isoform_B = comparator, as specified in the pairs file.
    # The GTF may contain many isoforms per gene; we filter to just these two.
    dom_exons <- gtf_data %>%
      filter(gene_id == pair$gene_id, transcript_id == pair$isoform_A)
    comp_exons <- gtf_data %>%
      filter(gene_id == pair$gene_id, transcript_id == pair$isoform_B)

    if (nrow(dom_exons) == 0 || nrow(comp_exons) == 0) {
      cat("  Warning: Missing exons for one or both transcripts\n")
      next
    }

    gene_strand <- unique(dom_exons$strand)[1]

    events <- detect_events_for_pair(
      dom_exons, comp_exons,
      pair$gene_id, pair$isoform_A, pair$isoform_B, gene_strand
    )

    if (nrow(events) > 0) {
      cat(sprintf("  Detected %d events: %s\n",
                  nrow(events),
                  paste(unique(events$event_type), collapse = ", ")))
      all_events[[length(all_events) + 1]] <- events
    } else {
      cat("  No events detected\n")
    }
  }

  if (length(all_events) > 0) {
    final_events <- bind_rows(all_events) %>%
      arrange(gene_id, dominant_transcript_id, comparator_transcript_id, event_type)

    cat(sprintf("\nWriting events to: %s\n", output_file))
    write_tsv(final_events, output_file)

    cat(sprintf("  Total events: %d\n", nrow(final_events)))
    cat(sprintf("  Event types: %s\n",
                paste(names(table(final_events$event_type)), collapse = ", ")))
  } else {
    cat("\nNo events detected!\n")
  }

  cat("\n═══════════════════════════════════════════════════════════════════\n")
  cat("EVENT DETECTION COMPLETE\n")
  cat("═══════════════════════════════════════════════════════════════════\n")
}

# ==============================================================================
# Command Line Interface
# ==============================================================================

if (!interactive()) {
  args <- commandArgs(trailingOnly = TRUE)

  if (length(args) != 3) {
    cat("Usage: detect_and_save_events.R <gtf_file> <pairs_file> <output_events_file>\n")
    quit(status = 1)
  }

  main(args[1], args[2], args[3])
} else {
  main(
    gtf_file = "synthetic_data/base_events.gtf",
    pairs_file = "synthetic_data/pairs.tsv",
    output_file = "synthetic_data/events_new.tsv"
  )
}
